export const mechanismCategories = {
  hormonal: { label: 'Hormonal', order: 1 }, metabolic: { label: 'Metabolic', order: 2 },
  neuro: { label: 'Neurotransmission & Cognition', order: 3 }, cellular: { label: 'Cellular & Molecular', order: 4 },
  immune: { label: 'Immune & Inflammation', order: 5 }, vascular: { label: 'Vascular & Cardiovascular', order: 6 },
  gut: { label: 'Gut & Microbiome', order: 7 }, structural: { label: 'Structural & Tissue', order: 8 },
};
export function mechanismsByCategory(category) {
  return Object.entries(mechanisms).filter(([,x]) => x.category === category).map(([slug,x]) => ({ slug, ...x }));
}
export function biomarkersForMechanism(mechanism, biomarkerSource = {}) {
  return (mechanism.biomarkers || []).map((slug) => biomarkerSource[slug] ? { slug, ...biomarkerSource[slug] } : null).filter(Boolean);
}
